            }
        } else if ((t & BASE_KIND) == OBJECT || (t & DIM) != 0) {
            // if t is any other reference or array type,
            // merge(u,t)=java/lang/Object
            v = OBJECT | cw.addType("java/lang/Object");
        } else {
            // if t is any other type, merge(u,t)=TOP
            v = TOP;
        }
